    qs.append(make_q(c, "QUANT_SDT", "medium", "A vehicle traveling at 54 km/h covers what distance in 20 seconds?", "300 m", "250 m", "350 m", "400 m", "A", "54 * (5/18) = 15 m/s. Distance = 15 * 20 = 300 m."))
