    qs.append(make_q(c, "QUANT_ADV", "easy", "Calculate the simple interest on Rs. 2,000 for 2 years at 5% per annum:", "Rs. 200", "Rs. 150", "Rs. 250", "Rs. 300", "A", "SI = (2000 * 5 * 2) / 100 = Rs. 200."))
