    qs.append(make_q(c, "LR_SEATING", "medium", "Four routers R1, R2, R3, R4 are in a rack row. R2 is between R1 and R3. R4 is to right of R3. Which router is at leftmost end?", "R1", "R2", "R3", "R4", "A", "Order: R1, R2, R3, R4. Leftmost is R1."))
    qs.append(make_q(c, "LR_PUZZLES", "medium", "Statements: All routers are network devices. All network devices process packets. Conclusion: All routers process packets.", "Follows", "Does not follow", "Cannot say", "Invalid", "A", "Transitive deduction holds."))
    qs.append(make_q(c, "LR_CODING", "medium", "If 'CELL' has letter positions 3-5-12-12, what is 'SITE'?", "19-9-20-5", "19-8-20-5", "18-9-20-5", "19-9-21-5", "A", "S=19, I=9, T=20, E=5."))
    qs.append(make_q(c, "LR_SERIES", "medium", "Find next: 80, 70, 61, 53, 46, ?", "40", "39", "41", "42", "A", "Differences: -10, -9, -8, -7. Next is -6 => 46 - 6 = 40."))
